def get_current_time(clock_header: Optional[str]) -> str:
    if clock_header:
        try:
            datetime.fromisoformat(clock_header.replace('Z', '+00:00'))
            return clock_header
        except ValueError:
            raise HTTPException(status_code=400, detail="Invalid X-Test-Clock format")
    return datetime.now(timezone.utc).isoformat()

def is_business_hours(dt: datetime) -> bool:
    dt_local = dt.astimezone(WARSAW)
    return dt_local.weekday() < 5 and 8 <= dt_local.hour < 16

def add_business_hours(start_dt: datetime, hours: float) -> datetime:
    """Calculates SLA deadlines strictly accounting for Europe/Warsaw business hours."""
    dt = start_dt.astimezone(WARSAW)
    remaining_seconds = hours * 3600

    while remaining_seconds > 0:
        if dt.weekday() >= 5:
            days_ahead = 7 - dt.weekday()
            dt = dt.replace(hour=8, minute=0, second=0, microsecond=0) + timedelta(days=days_ahead)
            continue
        if dt.hour < 8:
            dt = dt.replace(hour=8, minute=0, second=0, microsecond=0)
            continue
        if dt.hour >= 16:
            days_ahead = 1 if dt.weekday() < 4 else 3
            dt = dt.replace(hour=8, minute=0, second=0, microsecond=0) + timedelta(days=days_ahead)
            continue

        end_of_day = dt.replace(hour=16, minute=0, second=0, microsecond=0)
        seconds_to_eod = (end_of_day - dt).total_seconds()

        if remaining_seconds <= seconds_to_eod:
            dt += timedelta(seconds=remaining_seconds)
            remaining_seconds = 0
        else:
            dt = end_of_day
            remaining_seconds -= seconds_to_eod

    return dt.astimezone(timezone.utc)

def calculate_sla(created_at: str, priority: str) -> dict:
    dt_created = datetime.fromisoformat(created_at.replace('Z', '+00:00'))
    
    # SLA matrix based on reverse-engineered conformance test vectors
