@app.post("/tickets", status_code=201)
def create_ticket(
    ticket: TicketCreate, 
    x_test_clock: Optional[str] = Header(None, alias="X-Test-Clock")
):
    ticket_id = str(uuid.uuid4())
    created_at = get_current_time(x_test_clock)
    
    matrix = {
        (1, 1): "P1", (1, 2): "P2", (1, 3): "P3",
        (2, 1): "P2", (2, 2): "P3", (2, 3): "P4",
        (3, 1): "P3", (3, 2): "P4", (3, 3): "P4",
    }
    base_priority = matrix.get((ticket.impact, ticket.urgency), "P4")
    
    final_priority = base_priority
    if ticket.reporter.vip and base_priority in ["P3", "P4"]:
        final_priority = "P2"
        
    new_ticket = {
        "id": ticket_id,
        "title": ticket.title,
        "state": "new",
        "priority": final_priority,
        "created_at": created_at,
        "reporter": ticket.reporter.model_dump(),
        "sla": calculate_sla(created_at, final_priority)
    }
    
    tickets_db[ticket_id] = new_ticket
    return new_ticket

@app.get("/tickets")
def list_tickets(state: Optional[str] = None, priority: Optional[str] = None):
    results = list(tickets_db.values())
    if state:
        results = [t for t in results if t["state"] == state]
    if priority:
        results = [t for t in results if t["priority"] == priority]
    return results

@app.get("/tickets/{ticket_id}")
def get_ticket(ticket_id: str):
    if ticket_id not in tickets_db:
        raise HTTPException(status_code=404, detail="Ticket not found")
    return tickets_db[ticket_id]

@app.post("/tickets/{ticket_id}/{action}", status_code=200)
def transition_ticket(
    ticket_id: str, 
    action: str, 
    x_test_clock: Optional[str] = Header(None, alias="X-Test-Clock")
):
    if ticket_id not in tickets_db:
        raise HTTPException(status_code=404, detail="Not Found")
    
    ticket = tickets_db[ticket_id]
    current_state = ticket["state"]
    current_time = get_current_time(x_test_clock)
    
    if action == "ack":
        if current_state != "new": raise HTTPException(status_code=409, detail="Conflict")
        ticket["state"] = "acknowledged"
        ticket["acknowledged_at"] = current_time
        
    elif action == "start":
        if current_state != "acknowledged": raise HTTPException(status_code=409, detail="Conflict")
        ticket["state"] = "in_progress"
        ticket["started_at"] = current_time
        
    elif action == "resolve":
        if current_state != "in_progress": raise HTTPException(status_code=409, detail="Conflict")
        ticket["state"] = "resolved"
        ticket["resolved_at"] = current_time
        
    elif action == "close":
        if current_state != "resolved": raise HTTPException(status_code=409, detail="Conflict")
        ticket["state"] = "closed"
        ticket["closed_at"] = current_time
        
    elif action == "reopen":
        if current_state == "closed":
            raise HTTPException(status_code=409, detail="Ticket is immutable (C2)")
        if current_state != "resolved": 
            raise HTTPException(status_code=409, detail="Conflict")
            
        resolved_at = datetime.fromisoformat(ticket["resolved_at"].replace('Z', '+00:00'))
        now = datetime.fromisoformat(current_time.replace('Z', '+00:00'))
        if (now - resolved_at).total_seconds() > 7 * 86400:
            raise HTTPException(status_code=409, detail="Reopen window expired")
            
        ticket["state"] = "in_progress"
        
    else:
        raise HTTPException(status_code=404, detail="Invalid action")
        
    return ticket

@app.get("/tickets/{ticket_id}/sla")
def get_sla(ticket_id: str, x_test_clock: Optional[str] = Header(None, alias="X-Test-Clock")):
    if ticket_id not in tickets_db:
        raise HTTPException(status_code=404, detail="Not Found")
    
    ticket = tickets_db[ticket_id]
    current_time = get_current_time(x_test_clock)
    dt_now = datetime.fromisoformat(current_time.replace('Z', '+00:00'))
    
    ack_due = datetime.fromisoformat(ticket["sla"]["ack_due_at"].replace('Z', '+00:00'))
    resolve_due = datetime.fromisoformat(ticket["sla"]["resolve_due_at"].replace('Z', '+00:00'))
    
    if ticket.get("acknowledged_at"):
        dt_ack = datetime.fromisoformat(ticket["acknowledged_at"].replace('Z', '+00:00'))
        ack_breached = dt_ack > ack_due
    else:
        ack_breached = dt_now > ack_due

    if ticket.get("resolved_at"):
        dt_res = datetime.fromisoformat(ticket["resolved_at"].replace('Z', '+00:00'))
        resolve_breached = dt_res > resolve_due
    else:
        resolve_breached = dt_now > resolve_due
        
    return {
        "ack_breached": ack_breached,
        "resolve_breached": resolve_breached,
        "paused": not is_business_hours(dt_now)
    }